export const CALCULUS_INTRO_ACTIVITIES = [
{n:1,type:"mcq",micro:"Kecepatan rata-rata pada sebuah selang",q:"Sebuah mobil menempuh 120 km dalam 2 jam. Berapa kecepatan rata-ratanya selama perjalanan itu?",options:["60 km/jam","240 km/jam","2 km/jam"],answer:0,explain:"Kecepatan rata-rata = total jarak ÷ total waktu = 120 ÷ 2 = 60 km/jam.",hint:"Bagi jarak yang ditempuh dengan waktu yang dibutuhkan."},
{n:2,type:"mcq",micro:"Laju perubahan rata-rata umum",q:"Suhu naik dari 15°C menjadi 27°C selama 4 jam. Berapa laju perubahan rata-ratanya?",options:["48°C per jam","3°C per jam","12°C per jam"],answer:1,explain:"Laju perubahan rata-rata = perubahan nilai ÷ perubahan waktu = (27 − 15) ÷ 4 = 12 ÷ 4 = 3°C per jam.",hint:"Bagi selisih suhu dengan lama waktu."},
{n:3,type:"mcq",micro:"Rata-rata menyembunyikan variasi",q:"Kecepatan rata-rata sebuah perjalanan adalah 50 km/jam. Apakah ini berarti mobil selalu bergerak tepat 50 km/jam sepanjang perjalanan?",options:["Ya — rata-rata 50 berarti mobil selalu bergerak tepat 50 km/jam sepanjang perjalanan itu","Ya — kecepatan rata-rata hanya ada jika speedometer menunjukkan 50 sepanjang waktu","Tidak — mobil bisa lebih cepat di jalan tol dan lebih lambat di kemacetan, asalkan rata-ratanya 50"],answer:2,explain:"Rata-rata hanya merangkum keseluruhan; kecepatan sesaat bisa berubah-ubah selama perjalanan.",hint:"Bisakah sesuatu punya rata-rata 50 tanpa pernah benar-benar bernilai 50 setiap saat?"},
{n:4,type:"tf",micro:"Laju sesaat vs rata-rata",q:"Benar atau Salah: Kecepatan yang ditunjukkan spidometer mobil pada satu momen adalah kecepatan SESAAT, bukan kecepatan rata-rata.",answer:true,explain:"Spidometer menunjukkan seberapa cepat mobil bergerak tepat pada saat itu — laju perubahan sesaat, bukan rata-rata seluruh perjalanan.",hint:"Apakah spidometer menunjukkan kecepatan 'sekarang' atau 'rata-rata sejauh ini'?"},
{n:5,type:"mcq",micro:"Kecuraman yang berubah pada kurva",q:"Sebuah grafik jarak-waktu berbentuk kurva yang makin curam dari kiri ke kanan. Apa artinya tentang kecepatan?",options:["Kecepatannya bertambah seiring waktu (mobil mempercepat)","Kecepatannya tetap","Mobil berhenti"],answer:0,explain:"Kemiringan grafik jarak-waktu adalah kecepatan; kurva yang makin curam berarti kecepatan makin besar.",hint:"Grafik yang makin curam berarti jarak bertambah makin cepat — apa artinya untuk kecepatan?"},
{n:6,type:"mcq",micro:"Bagian mendatar berarti diam",q:"Pada grafik jarak-waktu, sebuah bagian yang mendatar (garis horizontal) menunjukkan...",options:["Objek bergerak dengan kecepatan tetap yang besar","Objek sedang diam (kecepatan nol)","Objek bergerak mundur menuju titik awalnya"],answer:1,explain:"Bagian mendatar berarti jarak tidak berubah meski waktu berjalan, jadi kecepatannya nol.",hint:"Jika posisi tidak berubah seiring waktu, seberapa cepat objek bergerak?"},
{n:7,type:"mcq",micro:"'Seberapa cepat sekarang'",q:"Pertanyaan 'seberapa cepat suhu naik TEPAT pada pukul 10:00' menanyakan laju perubahan...",options:["Rata-rata (selama seharian)","Total (jumlah kenaikan)","Sesaat (pada satu momen)"],answer:2,explain:"'Tepat pada pukul 10:00' merujuk pada satu momen tunggal, jadi ini laju perubahan sesaat.",hint:"Apakah pertanyaan ini tentang satu momen atau rentang waktu?"},
{n:8,type:"order",micro:"Menghitung laju perubahan rata-rata",q:"Urutkan langkah-langkah untuk menghitung laju perubahan rata-rata fungsi f dari x = a ke x = b.",items:["Bagi selisih nilai fungsi dengan selisih x: (f(b) − f(a)) ÷ (b − a)","Hitung nilai fungsi f(a) dan f(b)","Kenali kedua titik ujung selang, yaitu x = a dan x = b"],answer:[2,1,0],explain:"Kenali kedua ujung selang, hitung nilai fungsi di keduanya, lalu bagi selisih nilai fungsi dengan selisih x.",hint:"Kamu perlu nilai f(a) dan f(b) dulu sebelum bisa membaginya dengan (b − a)."},
{n:9,type:"mcq",micro:"Laju perubahan bisa negatif",q:"Air dalam tangki turun dari 100 liter menjadi 60 liter dalam 5 menit. Berapa laju perubahan rata-ratanya?",options:["−8 liter per menit","8 liter per menit","40 liter per menit"],answer:0,explain:"Laju = (60 − 100) ÷ 5 = −40 ÷ 5 = −8 liter per menit. Tanda negatif menunjukkan air berkurang.",hint:"Kurangkan nilai awal dari nilai akhir; hasilnya bisa negatif jika berkurang."},
{n:10,type:"mcq",micro:"Kecuraman terbesar pada kurva",q:"Pada sebuah kurva yang naik lalu mendatar di puncak lalu turun, di bagian mana kecuramannya (laju perubahan) paling mendekati nol?",options:["Di bagian paling curam saat kurva sedang naik","Di puncak (tempat kurva paling mendatar)","Di titik awal kurva sebelum kurva mulai naik"],answer:1,explain:"Di puncak, kurva sesaat mendatar, jadi laju perubahannya nol di sana.",hint:"Bagian mana dari kurva yang paling 'rata' sesaat?"},
{n:11,type:"mcq",micro:"Menghitung laju dari dua nilai fungsi",q:"Sebuah fungsi punya f(2) = 5 dan f(6) = 17. Berapa laju perubahan rata-rata dari x = 2 ke x = 6?",options:["12","4","3"],answer:2,explain:"Laju = (17 − 5) ÷ (6 − 2) = 12 ÷ 4 = 3.",hint:"Bagi perubahan f (yaitu 17 − 5) dengan perubahan x (yaitu 6 − 2)."},
{n:12,type:"mcq",micro:"Grafik jarak-waktu garis lurus",q:"Grafik jarak-waktu sebuah objek berupa garis lurus miring. Apa yang bisa disimpulkan tentang kecepatannya?",options:["Kecepatannya tetap (konstan)","Kecepatannya terus bertambah","Objek berhenti lalu bergerak"],answer:0,explain:"Garis lurus berarti kemiringannya tetap, jadi kecepatannya konstan sepanjang waktu.",hint:"Kemiringan garis lurus berubah atau tetap?"},
{n:13,type:"mcq",micro:"Kecuraman kurva berbeda di tiap titik",q:"Pada sebuah grafik berbentuk kurva (bukan garis lurus), kemiringan (laju perubahan) di berbagai titik...",options:["Selalu bernilai nol","Bisa berbeda-beda dari satu titik ke titik lain","Selalu sama di semua titik"],answer:1,explain:"Tidak seperti garis lurus, kurva melengkung sehingga kecuramannya berubah dari titik ke titik.",hint:"Apakah kurva parabola sama curamnya di setiap tempat, atau berbeda-beda?"},
{n:14,type:"mcq",micro:"Percepatan sebagai laju perubahan kecepatan",q:"Kecepatan sebuah mobil naik dari 0 menjadi 60 km/jam dalam 10 detik. Laju perubahan kecepatan (percepatan) rata-ratanya adalah...",options:["60 km/jam per detik","600 km/jam per detik","6 km/jam per detik"],answer:2,explain:"Percepatan rata-rata = (60 − 0) ÷ 10 = 6 km/jam per detik.",hint:"Percepatan adalah laju perubahan kecepatan — bagi perubahan kecepatan dengan waktu."},
{n:15,type:"mcq",micro:"Membaca kapan objek tercepat dari grafik",q:"Pada grafik jarak-waktu berbentuk kurva, objek bergerak paling cepat di bagian grafik yang...",options:["Paling curam","Paling mendatar","Paling dekat sumbu waktu"],answer:0,explain:"Kemiringan grafik jarak-waktu adalah kecepatan, jadi bagian paling curam menunjukkan kecepatan tertinggi.",hint:"Kecepatan tinggi berarti jarak bertambah cepat — bagian grafik seperti apa?"},
{n:16,type:"mcq",micro:"Laju perubahan nol berarti tidak berubah",q:"Jika laju perubahan sesaat sebuah besaran adalah nol pada suatu momen, artinya besaran itu pada momen tersebut...",options:["Berubah sangat cepat","Sesaat tidak sedang bertambah maupun berkurang","Bernilai nol"],answer:1,explain:"Laju perubahan nol berarti besaran itu sedang 'diam' sesaat — tidak naik dan tidak turun pada momen itu.",hint:"Laju perubahan tentang seberapa cepat sesuatu BERUBAH, bukan seberapa besar nilainya."},
{n:17,type:"tf",micro:"Turunan sebagai kemiringan garis singgung",q:"Benar atau Salah: Laju perubahan sesaat sebuah fungsi di sebuah titik sama dengan kemiringan garis singgung (garis yang menyentuh kurva) di titik itu.",answer:true,explain:"Garis singgung menyentuh kurva di satu titik dan menunjukkan arah kurva di sana; kemiringannya adalah laju perubahan sesaat.",hint:"Garis apa yang 'menempel' pada kurva di satu titik dan menunjukkan arahnya di titik itu?"},
{n:18,type:"mcq",micro:"Memperkecil selang mendekati laju sesaat",q:"Untuk memperkirakan laju perubahan sesaat sebuah fungsi di x = 3, kamu bisa menghitung laju rata-rata pada selang seperti x = 3 sampai x = 3,001. Semakin kecil selangnya...",options:["Semakin jauh hasilnya dari laju sesaat yang sebenarnya","Hasilnya selalu sama tanpa peduli seberapa kecil selangnya","Semakin dekat hasilnya ke laju sesaat sebenarnya"],answer:2,explain:"Saat selang menyusut mendekati satu titik, laju rata-rata menuju nilai laju sesaat — ini gagasan limit dalam kalkulus.",hint:"Jika kedua titik makin berdekatan, garis penghubungnya makin mirip dengan apa?"},
{n:19,type:"mcq",micro:"Gagasan limit secara informal",q:"Nilai 2 + 1/n untuk n = 10, 100, 1.000, 10.000 berturut-turut adalah 2,1; 2,01; 2,001; 2,0001. Nilai yang DIDEKATI oleh barisan ini saat n membesar tanpa batas adalah...",options:["2","2,1","Tak berhingga"],answer:0,explain:"Saat n makin besar, 1/n makin kecil menuju 0, jadi 2 + 1/n mendekati 2. Nilai yang didekati ini disebut limit.",hint:"Ke arah bilangan bulat mana angka-angka 2,1; 2,01; 2,001 menuju?"},
{n:20,type:"mcq",micro:"Kecepatan pada grafik yang turun",q:"Pada grafik posisi-waktu, sebuah bagian yang menurun (kemiringan negatif) menunjukkan objek...",options:["Diam","Bergerak kembali ke arah titik awal (posisi berkurang)","Bergerak maju lebih cepat"],answer:1,explain:"Kemiringan negatif pada grafik posisi-waktu berarti posisi berkurang, yaitu objek bergerak mundur.",hint:"Jika posisi (nilai y) berkurang seiring waktu, ke arah mana objek bergerak?"},
{n:21,type:"mcq",micro:"Garis tali busur",q:"Sebuah garis yang menghubungkan DUA titik pada sebuah kurva disebut garis tali busur (sekan). Kemiringan garis ini memberikan...",options:["Laju perubahan sesaat di satu titik","Nilai fungsi","Laju perubahan rata-rata di antara kedua titik itu"],answer:2,explain:"Kemiringan garis tali busur = (perubahan y) ÷ (perubahan x) antara kedua titik = laju perubahan rata-rata.",hint:"Garis yang memotong kurva di dua titik menunjukkan perubahan rata-rata atau sesaat?"},
{n:22,type:"mcq",micro:"Garis singgung",q:"Sebuah garis yang hanya MENYENTUH kurva di satu titik dan sejajar dengan arah kurva di titik itu disebut garis singgung. Kemiringannya memberikan...",options:["Laju perubahan sesaat di titik sentuh itu","Laju perubahan rata-rata","Luas di bawah kurva"],answer:0,explain:"Garis singgung menangkap arah kurva tepat di satu titik; kemiringannya adalah laju perubahan sesaat di sana (turunan).",hint:"Garis yang menyentuh di satu titik menunjukkan perubahan 'sekarang' atau 'rata-rata'?"},
{n:23,type:"mcq",micro:"Garis singgung mendatar di puncak",q:"Pada grafik parabola yang membuka ke bawah, garis singgung di titik puncak berbentuk...",options:["Sangat curam ke bawah","Mendatar (kemiringan nol)","Sangat curam ke atas"],answer:1,explain:"Di puncak, kurva sesaat mendatar, jadi garis singgungnya horizontal dengan kemiringan nol.",hint:"Bagaimana bentuk kurva tepat di titik tertingginya — naik, turun, atau rata?"},
{n:24,type:"mcq",micro:"Tanda turunan pada bagian naik",q:"Di bagian grafik tempat kurva NAIK dari kiri ke kanan, kemiringan garis singgung (turunan) bernilai...",options:["Negatif","Nol","Positif"],answer:2,explain:"Kurva yang naik memiliki garis singgung yang miring ke atas, jadi kemiringannya (turunannya) positif.",hint:"Garis yang miring ke atas punya kemiringan positif atau negatif?"},
{n:25,type:"mcq",micro:"Tanda turunan pada bagian turun",q:"Di bagian grafik tempat kurva TURUN dari kiri ke kanan, turunannya bernilai...",options:["Negatif","Positif","Nol"],answer:0,explain:"Kurva yang turun memiliki garis singgung yang miring ke bawah, jadi turunannya negatif.",hint:"Garis yang miring ke bawah punya kemiringan bertanda apa?"},
{n:26,type:"classify",micro:"Mencocokkan bentuk kurva dengan tanda turunan",q:"Kelompokkan setiap keadaan kurva ke dalam 'Turunan positif', 'Turunan negatif', atau 'Turunan nol'.",items:["Kurva sedang naik curam","Kurva sedang menurun","Kurva sedang di puncak (mendatar sesaat)","Kurva sedang di titik terendah lembah (mendatar sesaat)"],groups:["Turunan positif","Turunan negatif","Turunan nol"],answer:{"Turunan positif":["Kurva sedang naik curam"],"Turunan negatif":["Kurva sedang menurun"],"Turunan nol":["Kurva sedang di puncak (mendatar sesaat)","Kurva sedang di titik terendah lembah (mendatar sesaat)"]},explain:"Naik → turunan positif; turun → turunan negatif; mendatar sesaat (baik di puncak maupun lembah) → turunan nol.",hint:"Bayangkan garis singgung di tiap keadaan: miring ke atas, miring ke bawah, atau datar?"},
{n:27,type:"tf",micro:"Garis singgung bisa memotong kurva di tempat lain",q:"Benar atau Salah: Garis singgung sebuah kurva di suatu titik hanya menyentuh titik itu dan tidak pernah menyentuh atau memotong bagian kurva mana pun yang lain.",answer:false,explain:"Garis singgung menyentuh kurva secara 'menyinggung' di titik yang dimaksud, tetapi garis yang sama bisa saja memotong bagian kurva lain yang jauh dari titik itu.",hint:"Apakah definisi garis singgung membatasi apa yang terjadi di seluruh grafik, atau hanya di sekitar titik sentuh?"},
{n:28,type:"mcq",micro:"Membaca kemiringan garis singgung dari grafik",q:"Sebuah garis singgung pada kurva di titik P melewati (2, 3) dan (4, 9). Berapa kemiringan garis singgung itu (yaitu turunan di P)?",options:["2","3","6"],answer:1,explain:"Kemiringan = (9 − 3) ÷ (4 − 2) = 6 ÷ 2 = 3.",hint:"Pakai (perubahan y) ÷ (perubahan x) untuk kedua titik pada garis singgung."},
{n:29,type:"mcq",micro:"Grafik turunan dari grafik fungsi",q:"Sebuah fungsi naik, lalu mencapai puncak, lalu turun. Grafik turunannya (f') akan...",options:["Selalu positif","Berupa garis mendatar","Positif, lalu nol tepat di puncak, lalu negatif"],answer:2,explain:"Turunan mencerminkan kemiringan: positif saat fungsi naik, nol di puncak, negatif saat fungsi turun.",hint:"Terjemahkan 'naik, puncak, turun' menjadi tanda kemiringan: +, 0, −."},
{n:30,type:"order",micro:"Memperkirakan turunan dari grafik",q:"Urutkan langkah-langkah untuk memperkirakan turunan sebuah fungsi di titik x = 4 dari grafiknya.",items:["Hitung kemiringan garis singgung itu sebagai perubahan y dibagi perubahan x","Temukan titik pada kurva di x = 4","Gambar garis yang menyentuh kurva (garis singgung) di titik itu"],answer:[1,2,0],explain:"Temukan titiknya, gambar garis singgung di sana, lalu hitung kemiringan garis singgung itu.",hint:"Kamu harus punya garis singgungnya dulu sebelum bisa menghitung kemiringannya."},
{n:31,type:"mcq",micro:"Turunan konstan berarti garis lurus",q:"Sebuah fungsi memiliki turunan yang bernilai TETAP 5 di setiap titik. Grafik fungsinya adalah...",options:["Garis lurus dengan kemiringan 5","Parabola","Kurva yang makin curam"],answer:0,explain:"Turunan tetap berarti kemiringan tidak pernah berubah — itulah ciri garis lurus, dengan kemiringan sama dengan nilai turunannya.",hint:"Kemiringan yang sama di mana-mana menghasilkan bentuk grafik apa?"},
{n:32,type:"mcq",micro:"Titik belok dari garis singgung mendatar",q:"Pada sebuah grafik, ada dua tempat garis singgungnya mendatar: satu di puncak lokal dan satu di lembah lokal. Kedua tempat ini disebut...",options:["Titik asimtot","Titik stasioner (turunan sama dengan nol)","Titik potong sumbu x"],answer:1,explain:"Tempat dengan garis singgung mendatar (turunan nol) disebut titik stasioner; bisa berupa maksimum lokal, minimum lokal, atau titik belok datar.",hint:"Kedua tempat itu punya kesamaan: turunannya bernilai berapa?"},
{n:33,type:"tf",micro:"Turunan positif berarti fungsi naik",q:"Benar atau Salah: Pada selang di mana turunan sebuah fungsi selalu positif, fungsi itu selalu TURUN di sepanjang selang tersebut.",answer:false,explain:"Justru sebaliknya: turunan positif berarti kemiringan selalu ke atas, sehingga fungsi selalu NAIK di selang itu. Turunan negatif yang berarti fungsi turun.",hint:"Garis singgung yang miring ke atas (kemiringan positif) berarti nilai fungsi bergerak ke arah mana?"},
{n:34,type:"mcq",micro:"Garis tali busur mendekati garis singgung",q:"Pada sebuah grafik, titik B digeser makin dekat ke titik A di sepanjang kurva. Garis tali busur AB akan makin menyerupai...",options:["Garis tegak","Sumbu mendatar","Garis singgung di titik A"],answer:2,explain:"Saat B mendekati A, kemiringan tali busur AB menuju kemiringan garis singgung di A — inilah bagaimana laju rata-rata menjadi laju sesaat.",hint:"Dua titik yang makin berdekatan menghasilkan garis penghubung yang makin mirip dengan garis yang menyentuh di satu titik."},
{n:35,type:"mcq",micro:"Membaca kecepatan dari grafik posisi",q:"Sebuah grafik posisi-waktu naik landai, lalu naik curam, lalu mendatar. Objek itu bergerak...",options:["Lambat, lalu cepat, lalu berhenti","Cepat, lalu lambat, lalu mundur","Diam sepanjang waktu"],answer:0,explain:"Kemiringan landai = kecepatan kecil; kemiringan curam = kecepatan besar; mendatar = berhenti.",hint:"Terjemahkan tiap bagian kemiringan menjadi kata: landai, curam, datar."},
{n:36,type:"mcq",micro:"Grafik turunan dari garis lurus",q:"Sebuah fungsi grafiknya berupa garis lurus miring ke atas dengan kemiringan 3. Grafik turunannya (f') berupa...",options:["Parabola","Garis mendatar pada ketinggian 3","Garis miring yang sama"],answer:1,explain:"Turunan garis lurus adalah kemiringannya yang tetap, jadi grafik f' adalah garis horizontal di nilai 3.",hint:"Jika kemiringannya 3 di mana-mana, seperti apa grafik 'kemiringan terhadap x'?"},
{n:37,type:"tf",micro:"Turunan nol tidak selalu berarti maksimum",q:"Benar atau Salah: Jika turunan sebuah fungsi nol di sebuah titik, titik itu pasti merupakan nilai maksimum fungsi.",answer:false,explain:"Turunan nol menandai titik stasioner, yang bisa berupa maksimum lokal, minimum lokal, ATAU titik belok datar — perlu pemeriksaan lebih lanjut untuk memastikan jenisnya.",hint:"Apakah lembah (titik terendah) juga punya garis singgung mendatar?"},
{n:38,type:"mcq",micro:"Kecuraman terbesar berarti turunan terbesar",q:"Pada sebuah kurva naik, di titik mana turunannya bernilai paling besar?",options:["Di titik tempat kurva paling mendatar","Di titik potong sumbu y","Di titik tempat kurva paling curam menanjak"],answer:2,explain:"Turunan mengukur kecuraman; nilainya paling besar (paling positif) di tempat kurva menanjak paling tajam.",hint:"Turunan besar sama dengan kemiringan besar — bagian kurva mana yang paling curam?"},
{n:39,type:"mcq",micro:"Membandingkan turunan dua fungsi dari grafik",q:"Grafik fungsi f lebih curam daripada grafik fungsi g di dekat x = 1. Di x = 1, mana yang benar?",options:["Turunan f lebih besar daripada turunan g","Turunan g lebih besar daripada turunan f","Turunan f dan g pasti sama besar di x = 1"],answer:0,explain:"Grafik yang lebih curam berarti kemiringan lebih besar, jadi turunan f lebih besar daripada turunan g di titik itu.",hint:"Curam = kemiringan besar = turunan besar."},
{n:40,type:"order",micro:"Mengurutkan gagasan menuju turunan",q:"Urutkan gagasan-gagasan ini dari yang paling dasar ke yang paling maju dalam membangun konsep turunan.",items:["Turunan: nilai yang didekati kemiringan tali busur saat kedua titik menyatu","Kemiringan garis tali busur antara dua titik = laju perubahan rata-rata","Saat kedua titik makin berdekatan, tali busur mendekati garis singgung"],answer:[1,2,0],explain:"Mulai dari laju rata-rata (tali busur), lalu perkecil selangnya (menuju garis singgung), lalu limitnya adalah turunan.",hint:"Konsep mana yang tidak memakai gagasan limit sama sekali? Itu yang paling dasar."},
{n:41,type:"mcq",micro:"Rumus laju perubahan rata-rata",q:"Laju perubahan rata-rata fungsi f dari x = a ke x = b dihitung dengan...",options:["(f(b) + f(a)) ÷ 2","(f(b) − f(a)) ÷ (b − a)","f(b) × f(a)"],answer:1,explain:"Ini adalah kemiringan garis tali busur: perubahan nilai fungsi dibagi perubahan x.",hint:"Bentuknya sama dengan rumus kemiringan garis: 'naik dibagi mendatar'."},
{n:42,type:"mcq",micro:"Menghitung laju rata-rata f(x) = x²",q:"Untuk f(x) = x², berapa laju perubahan rata-rata dari x = 1 ke x = 3?",options:["8","2","4"],answer:2,explain:"f(1) = 1, f(3) = 9. Laju = (9 − 1) ÷ (3 − 1) = 8 ÷ 2 = 4.",hint:"Hitung f(3) dan f(1), lalu bagi selisihnya dengan (3 − 1)."},
{n:43,type:"mcq",micro:"Aturan pangkat",q:"Aturan pangkat untuk turunan menyatakan bahwa turunan dari xⁿ adalah...",options:["n · xⁿ⁻¹","xⁿ⁺¹ ÷ (n + 1)","n · xⁿ"],answer:0,explain:"Turunan xⁿ = n · xⁿ⁻¹: turunkan pangkat menjadi koefisien, lalu kurangi pangkat dengan 1.",hint:"Pangkatnya 'turun' menjadi pengali di depan, dan pangkat yang baru berkurang 1."},
{n:44,type:"mcq",micro:"Turunan x²",q:"Jika f(x) = x², berapa turunannya f'(x)?",options:["2","2x","x"],answer:1,explain:"Dengan aturan pangkat: turunan x² = 2 · x²⁻¹ = 2x.",hint:"Turunkan pangkat 2 ke depan, kurangi pangkatnya menjadi 1."},
{n:45,type:"mcq",micro:"Turunan x³",q:"Jika f(x) = x³, berapa f'(x)?",options:["x²","3x","3x²"],answer:2,explain:"Turunan x³ = 3 · x³⁻¹ = 3x².",hint:"Pangkat 3 turun ke depan; pangkat baru adalah 3 − 1."},
{n:46,type:"mcq",micro:"Turunan konstanta",q:"Jika f(x) = 7 (fungsi konstan), berapa f'(x)?",options:["0","7","1"],answer:0,explain:"Fungsi konstan tidak berubah, jadi laju perubahannya selalu nol: f'(x) = 0.",hint:"Grafik y = 7 adalah garis mendatar — berapa kemiringannya?"},
{n:47,type:"mcq",micro:"Turunan ax + b",q:"Jika f(x) = 5x + 2, berapa f'(x)?",options:["2","5","5x"],answer:1,explain:"Turunan 5x adalah 5 (kemiringannya), dan turunan konstanta 2 adalah 0, jadi f'(x) = 5.",hint:"Fungsi linear f(x) = mx + b punya turunan yang sama dengan kemiringannya, m."},
{n:48,type:"mcq",micro:"Turunan penjumlahan",q:"Turunan dari sebuah penjumlahan, seperti f(x) = x² + x³, dihitung dengan...",options:["Menurunkan tiap suku lalu mengalikannya satu sama lain: 2x × 3x² = 6x³","Menurunkan hanya suku pertama dan mengabaikan suku lain karena penjumlahan tidak diturunkan","Menurunkan tiap suku secara terpisah lalu menjumlahkannya: 2x + 3x²"],answer:2,explain:"Turunan penjumlahan adalah jumlah turunan tiap sukunya, jadi f'(x) = 2x + 3x².",hint:"Bisakah kamu menurunkan x² dan x³ satu per satu, lalu menggabungkan hasilnya?"},
{n:49,type:"mcq",micro:"Turunan suku dengan koefisien",q:"Jika f(x) = 4x², berapa f'(x)?",options:["8x","4x","2x"],answer:0,explain:"Turunan 4x² = 4 · (2x) = 8x. Koefisien tetap ikut dikalikan.",hint:"Turunkan x² menjadi 2x, lalu tetap kalikan dengan koefisien 4."},
{n:50,type:"mcq",micro:"Mengevaluasi turunan di sebuah titik",q:"Jika f(x) = x², maka f'(x) = 2x. Berapa nilai turunan di x = 3, yaitu f'(3)?",options:["3","6","9"],answer:1,explain:"f'(x) = 2x, jadi f'(3) = 2 × 3 = 6. Ini adalah kemiringan kurva y = x² di titik x = 3.",hint:"Substitusikan x = 3 ke dalam f'(x) = 2x."},
{n:51,type:"open",micro:"Menurunkan dan mengevaluasi sebuah polinomial",q:"Diberikan f(x) = x³ + 2x² − 5x + 4. Cari f'(x), lalu hitung f'(2).",explain:"Aturan pangkat diterapkan suku demi suku; konstanta hilang; lalu substitusikan nilai x.",hint:"Turunkan setiap suku dengan aturan pangkat, jumlahkan, lalu masukkan x = 2.",sample:"Turunkan tiap suku: turunan x³ adalah 3x²; turunan 2x² adalah 4x; turunan −5x adalah −5; turunan 4 (konstanta) adalah 0. Jadi f'(x) = 3x² + 4x − 5. Evaluasi di x = 2: f'(2) = 3(4) + 4(2) − 5 = 12 + 8 − 5 = 15."},
{n:52,type:"mcq",micro:"Turunan sebagai fungsi baru",q:"Turunan f'(x) dari sebuah fungsi f(x) adalah...",options:["Satu bilangan tetap","Sama dengan f(x) itu sendiri","Sebuah fungsi baru yang memberi kemiringan f di setiap nilai x"],answer:2,explain:"f'(x) adalah fungsi; memasukkan nilai x tertentu ke f'(x) memberi kemiringan kurva f di titik itu.",hint:"Apakah f'(x) menghasilkan angka yang berbeda untuk nilai x yang berbeda?"},
{n:53,type:"mcq",micro:"Notasi turunan",q:"Notasi 'dy/dx' dan 'f'(x)' keduanya berarti...",options:["Turunan y terhadap x — laju perubahan sesaat","Perkalian d dengan y dibagi d dengan x","Nilai y saat x = 0"],answer:0,explain:"'dy/dx' dan 'f'(x)' adalah dua cara menulis turunan yang sama; keduanya melambangkan laju perubahan sesaat.",hint:"Kedua notasi ini merujuk pada konsep yang sama — apa itu?"},
{n:54,type:"mcq",micro:"Mencari titik stasioner",q:"Untuk f(x) = x² − 6x + 5, turunannya f'(x) = 2x − 6. Pada nilai x berapa fungsi ini memiliki titik stasioner (f'(x) = 0)?",options:["x = 5","x = 3","x = 6"],answer:1,explain:"Setarakan turunan dengan nol: 2x − 6 = 0, jadi x = 3. Di sini garis singgung mendatar.",hint:"Selesaikan 2x − 6 = 0."},
{n:55,type:"mcq",micro:"Nilai fungsi di titik stasioner",q:"Untuk f(x) = x² − 6x + 5 dengan titik stasioner di x = 3, berapa nilai f(3)?",options:["5","3","−4"],answer:2,explain:"f(3) = 3² − 6(3) + 5 = 9 − 18 + 5 = −4. Titik stasionernya di (3, −4).",hint:"Substitusikan x = 3 ke f(x) yang asli, bukan ke turunannya."},
{n:56,type:"open",micro:"Kecepatan dari fungsi posisi",q:"Posisi sebuah benda (dalam meter) pada waktu t detik adalah s(t) = t² + 2t. Cari fungsi kecepatannya v(t) sebagai turunan dari s(t), lalu hitung kecepatan pada t = 4 detik.",explain:"Dalam gerak, kecepatan adalah laju perubahan posisi terhadap waktu — yaitu turunan fungsi posisi.",hint:"Turunkan s(t) suku demi suku untuk mendapat v(t), lalu masukkan t = 4.",sample:"Kecepatan adalah turunan posisi: v(t) = s'(t). Turunan t² adalah 2t; turunan 2t adalah 2. Jadi v(t) = 2t + 2. Pada t = 4: v(4) = 2(4) + 2 = 8 + 2 = 10 m/detik."},
{n:57,type:"mcq",micro:"Turunan garis lurus selalu tetap",q:"Untuk f(x) = 3x − 7, berapa f'(x), dan apakah nilainya berubah tergantung x?",options:["f'(x) = 3, tetap untuk semua x","f'(x) = 3x, berubah","f'(x) = −7, tetap"],answer:0,explain:"Turunan fungsi linear adalah kemiringannya yang konstan: f'(x) = 3, sama di setiap titik.",hint:"Garis lurus punya kemiringan yang sama di mana-mana."},
{n:58,type:"mcq",micro:"Turunan nol berarti mendatar",q:"Jika f'(5) = 0, apa yang bisa disimpulkan tentang grafik f di x = 5?",options:["Garis singgung di x = 5 tegak lurus terhadap sumbu x","Garis singgung di x = 5 mendatar (kurva sesaat rata)","Grafik f memotong sumbu x tepat di x = 5"],answer:1,explain:"Turunan nol di suatu titik berarti kemiringan kurva di sana nol, yaitu garis singgungnya horizontal.",hint:"f'(5) adalah kemiringan di x = 5 — kemiringan 0 berarti apa?"},
{n:59,type:"mcq",micro:"Laju rata-rata mendekati sesaat",q:"Untuk f(x) = x², laju perubahan rata-rata dari x = 3 ke x = 3,01 adalah (9,0601 − 9) ÷ 0,01 = 6,01. Nilai ini mendekati turunan f'(3), yang sama dengan...",options:["9","3","6"],answer:2,explain:"f'(x) = 2x, jadi f'(3) = 6. Laju rata-rata pada selang yang sangat kecil (6,01) mendekati nilai sesaat 6.",hint:"Hitung 2x di x = 3."},
{n:60,type:"mcq",micro:"Gagasan luas di bawah kurva",q:"Dalam kalkulus, selain turunan (tentang kemiringan/laju perubahan), ada konsep integral yang menghitung...",options:["Luas di bawah kurva sebuah fungsi (akumulasi total)","Titik potong kurva dengan sumbu y dari fungsi tersebut","Kemiringan garis singgung tertinggi dari sebuah fungsi"],answer:0,explain:"Integral menghitung luas di antara kurva dan sumbu x, yang mewakili jumlah total yang terakumulasi (misalnya jarak dari grafik kecepatan-waktu).",hint:"Turunan tentang kemiringan; konsep pasangannya tentang apa yang terkumpul di bawah kurva?"},
{n:61,type:"open",micro:"Rata-rata vs sesaat",q:"Jelaskan perbedaan antara 'kecepatan rata-rata sebuah perjalanan' dan 'kecepatan sesaat pada satu momen', dan mengapa keduanya bisa sangat berbeda.",explain:"Rata-rata memampatkan seluruh perilaku menjadi satu angka; sesaat menangkap satu momen, dan momen-momen itu bisa sangat beragam.",hint:"Bisakah rata-rata sebuah perjalanan 50 km/jam meski mobil tidak pernah tepat 50 km/jam pada momen mana pun?",sample:"Kecepatan rata-rata = total jarak ÷ total waktu; ia merangkum keseluruhan perjalanan dalam satu angka. Kecepatan sesaat adalah seberapa cepat kamu bergerak tepat pada satu momen (yang ditunjukkan spidometer). Keduanya bisa jauh berbeda: dalam perjalanan 2 jam sejauh 100 km (rata-rata 50 km/jam), kamu mungkin melaju 100 km/jam di jalan tol dan 0 km/jam saat berhenti di lampu merah. Kecepatan sesaat berubah terus, sedangkan rata-rata hanya satu nilai untuk seluruh perjalanan."},
{n:62,type:"mcq",micro:"Turunan nol di puncak parabola",q:"Untuk f(x) = −x² + 6x (parabola membuka ke bawah), f'(x) = −2x + 6. Menyetarakan f'(x) = 0 memberi x = 3. Titik ini adalah...",options:["Nilai minimum fungsi, karena parabola membuka ke atas","Nilai maksimum fungsi, karena parabola membuka ke bawah","Titik potong fungsi dengan sumbu x, karena turunan sama dengan nol"],answer:1,explain:"Titik stasioner parabola yang membuka ke bawah adalah puncaknya — nilai maksimum. f(3) = −9 + 18 = 9 adalah nilai maksimumnya.",hint:"Parabola membuka ke bawah — titik stasionernya di bagian atas atau bawah?"},
{n:63,type:"mcq",micro:"Membaca naik/turun dari tanda turunan",q:"Sebuah fungsi punya f'(x) = 2x − 4. Untuk x < 2, f'(x) negatif; untuk x > 2, f'(x) positif. Ini berarti fungsi...",options:["Selalu naik","Selalu turun","Turun sebelum x = 2, lalu naik setelah x = 2 (jadi x = 2 adalah minimum)"],answer:2,explain:"Turunan negatif → fungsi turun; turunan positif → fungsi naik. Berubah dari turun ke naik di x = 2 menandakan titik minimum di sana.",hint:"Turun lalu naik membentuk lembah — di dasar lembah itu maksimum atau minimum?"},
{n:64,type:"mcq",micro:"Kesalahan aturan pangkat",q:"Seorang siswa menghitung turunan x⁴ sebagai 4x⁴. Apa kesalahannya?",options:["Ia lupa mengurangi pangkatnya — seharusnya 4x³","Ia seharusnya menulis x⁴ ÷ 4","Tidak ada kesalahan"],answer:0,explain:"Aturan pangkat: turunan xⁿ = n · xⁿ⁻¹. Untuk x⁴, pangkat baru adalah 4 − 1 = 3, jadi turunannya 4x³.",hint:"Setelah menurunkan pangkat ke depan sebagai pengali, pangkat yang tersisa harus berkurang berapa?"},
{n:65,type:"tf",micro:"Turunan konstanta selalu nol",q:"Benar atau Salah: Turunan dari suku konstanta apa pun (seperti +9 atau −3) selalu nol.",answer:true,explain:"Konstanta tidak berubah saat x berubah, jadi laju perubahannya nol; dalam menurunkan polinomial, suku konstanta selalu hilang.",hint:"Grafik y = konstanta adalah garis mendatar — berapa kemiringannya?"},
{n:66,type:"open",micro:"Mengapa memperkecil selang mendekati laju sesaat",q:"Jelaskan mengapa menghitung laju perubahan rata-rata pada selang yang makin kecil (misalnya x = 2 ke 2,1; lalu 2 ke 2,01; lalu 2 ke 2,001) memberi perkiraan yang makin baik untuk laju perubahan sesaat di x = 2.",explain:"Laju sesaat adalah limit dari laju rata-rata saat lebar selang menuju nol; secara grafik, tali busur menuju garis singgung.",hint:"Apa yang terjadi pada garis tali busur ketika kedua titiknya hampir menyatu?",sample:"Laju rata-rata pada sebuah selang adalah kemiringan garis tali busur yang menghubungkan dua titik pada kurva. Saat titik kedua digeser makin dekat ke x = 2, garis tali busur itu makin berimpit dengan garis singgung di x = 2. Kemiringan garis singgung inilah laju sesaat. Jadi makin kecil selangnya, makin dekat kemiringan tali busur ke kemiringan garis singgung — makin akurat perkiraan laju sesaatnya. Gagasan 'nilai yang didekati saat selang menyusut ke nol' adalah inti dari limit dalam kalkulus."},
{n:67,type:"mcq",micro:"Turunan dari turunan (percepatan)",q:"Jika posisi adalah s(t), maka kecepatan v(t) adalah turunan s(t). Percepatan a(t) adalah...",options:["Selalu nol","Turunan dari v(t) — yaitu turunan kedua dari s(t)","Sama dengan s(t)"],answer:1,explain:"Percepatan adalah laju perubahan kecepatan, jadi ia adalah turunan v(t), atau turunan yang diterapkan dua kali pada s(t).",hint:"Kecepatan adalah laju perubahan posisi; percepatan adalah laju perubahan apa?"},
{n:68,type:"mcq",micro:"Titik stasioner bukan berarti nilai nol",q:"Fungsi f(x) = x² + 4 punya turunan f'(x) = 2x, dan titik stasionernya di x = 0. Nilai fungsi di titik stasioner ini adalah f(0) = 4, BUKAN 0. Mengapa?",options:["Karena f'(x) = 0 berarti nilai fungsinya juga nol, sehingga f(0) = 0 pada titik stasioner itu","Karena titik stasioner selalu berada di sumbu x, jadi nilai fungsi di sana pasti sama dengan nol","Karena f'(x) = 0 hanya berarti garis singgung mendatar, bukan bahwa nilai fungsinya nol"],answer:2,explain:"Turunan nol menandakan kemiringan nol di titik itu; nilai fungsi di sana bisa berapa saja — di sini minimum fungsinya adalah 4.",hint:"Apa yang sebenarnya 'nol' di titik stasioner — nilai f atau nilai f'?"},
{n:69,type:"open",micro:"Menemukan dan mengklasifikasi titik stasioner",q:"Diberikan f(x) = x² − 8x + 10. Cari f'(x), tentukan titik stasionernya, dan jelaskan apakah itu maksimum atau minimum beserta alasannya.",explain:"Setarakan turunan dengan nol untuk titik stasioner; tentukan jenisnya dari arah bukaan parabola atau dari perubahan tanda turunan di sekitar titik itu.",hint:"Selesaikan 2x − 8 = 0, lalu perhatikan apakah parabolanya membuka ke atas atau ke bawah.",sample:"f'(x) = 2x − 8. Titik stasioner: 2x − 8 = 0, jadi x = 4. Nilai fungsi: f(4) = 16 − 32 + 10 = −6, jadi titik stasionernya di (4, −6). Ini adalah MINIMUM karena grafik y = x² − 8x + 10 adalah parabola yang membuka ke atas (koefisien x² positif). Bisa juga diperiksa dari tanda turunan: untuk x < 4, f'(x) negatif (fungsi turun); untuk x > 4, f'(x) positif (fungsi naik) — turun lalu naik berarti lembah/minimum."},
{n:70,type:"mcq",micro:"Turunan fungsi yang menurun",q:"Sebuah tangki bocor sehingga volumenya V(t) = 200 − 10t (liter, t menit). Turunan V'(t) = −10 berarti...",options:["Volume berkurang dengan laju tetap 10 liter per menit","Volume bertambah dengan laju tetap 10 liter per menit","Volume tetap 200 liter selama 10 menit pertama"],answer:0,explain:"Turunan negatif tetap (−10) berarti volume terus berkurang dengan laju konstan 10 liter/menit.",hint:"Tanda negatif pada turunan berarti besaran bertambah atau berkurang?"},
{n:71,type:"mcq",micro:"Kapan turunan tidak membantu",q:"Untuk fungsi konstan f(x) = 12, turunannya selalu 0. Ini memberitahu kita bahwa fungsi itu...",options:["Punya banyak titik maksimum","Tidak pernah naik atau turun — nilainya selalu tetap","Selalu naik"],answer:1,explain:"Turunan 0 di mana-mana berarti fungsi tidak berubah sama sekali — grafiknya garis mendatar.",hint:"Jika laju perubahan selalu nol, apakah nilainya pernah berubah?"},
{n:72,type:"open",micro:"Menafsirkan turunan dalam konteks",q:"Biaya total memproduksi x unit barang adalah C(x), dan turunannya C'(x) disebut 'biaya marjinal'. Jelaskan apa arti C'(100) = 5.000 dalam konteks nyata.",explain:"Turunan dari fungsi biaya adalah biaya marjinal: perkiraan tambahan biaya untuk satu unit lebih pada tingkat produksi saat ini.",hint:"Turunan mengukur perubahan output per satu satuan perubahan input — di sini, tambahan biaya per tambahan satu unit.",sample:"C'(100) = 5.000 berarti pada tingkat produksi 100 unit, biaya untuk memproduksi SATU unit tambahan (unit ke-101) kira-kira Rp5.000. Turunan biaya menunjukkan seberapa cepat biaya total naik per unit tambahan pada tingkat produksi tertentu. Ini berguna untuk memutuskan apakah memproduksi lebih banyak menguntungkan: jika harga jual per unit lebih dari Rp5.000, menambah produksi masih menguntungkan."},
{n:73,type:"mcq",micro:"Laju perubahan rata-rata nol",q:"Sebuah bola dilempar ke atas dan kembali ke tangan pada ketinggian yang sama. Laju perubahan RATA-RATA ketinggian selama seluruh lemparan adalah...",options:["Sama dengan kecepatan lemparan","Selalu positif","Nol, karena ketinggian awal dan akhir sama"],answer:2,explain:"Laju rata-rata = (ketinggian akhir − ketinggian awal) ÷ waktu = 0 ÷ waktu = 0, meski bola jelas bergerak (kecepatan sesaatnya tidak nol).",hint:"Jika titik awal dan akhir punya nilai yang sama, berapa selisihnya?"},
{n:74,type:"mcq",micro:"Membedakan f(x) dan f'(x)",q:"Untuk f(x) = x², kita punya f(4) = 16 dan f'(4) = 8. Angka 16 dan 8 berturut-turut adalah...",options:["Nilai fungsi di x = 4, dan kemiringan kurva di x = 4","Kemiringan kurva di x = 4, dan nilai fungsi di x = 4","Luas di bawah kurva dan panjang kurva di x = 4"],answer:0,explain:"f(4) = 16 adalah tinggi kurva di x = 4; f'(4) = 8 adalah kemiringan kurva di titik itu.",hint:"f memberi tinggi kurva; f' memberi kecuraman kurva."},
{n:75,type:"open",micro:"Mengapa turunan garis lurus tetap",q:"Jelaskan mengapa turunan setiap fungsi linear f(x) = mx + b selalu sama dengan m di setiap titik, tanpa perlu limit yang rumit.",explain:"Untuk garis lurus, kemiringan tak berubah, jadi turunannya adalah konstanta m; tidak dibutuhkan proses limit karena tali busur mana pun sudah berimpit dengan garisnya.",hint:"Apa yang membuat garis 'lurus', dan bagaimana kaitannya dengan kemiringan di berbagai titik?",sample:"Grafik f(x) = mx + b adalah garis lurus. Sebuah garis lurus punya kemiringan yang sama di setiap titiknya — itulah arti 'lurus'. Karena turunan adalah kemiringan kurva di sebuah titik, dan kemiringan garis ini di mana-mana adalah m, maka f'(x) = m untuk semua x. Konstanta b hanya menggeser garis ke atas atau bawah tanpa mengubah kemiringannya, jadi ia tidak memengaruhi turunan."},
{n:76,type:"mcq",micro:"Turunan menunjukkan arah perubahan",q:"Populasi sebuah kota dimodelkan P(t), dan pada suatu tahun P'(t) = −1.500. Ini berarti pada tahun itu populasi kota...",options:["Sedang bertambah dengan laju sekitar 1.500 orang per tahun","Sedang menurun dengan laju sekitar 1.500 orang per tahun","Tetap sama besar karena tanda negatif hanya hiasan dalam turunan"],answer:1,explain:"Turunan negatif berarti besaran sedang menurun; besarnya (1.500) adalah laju penurunan per satuan waktu.",hint:"Tanda negatif pada turunan populasi menunjukkan pertumbuhan atau penyusutan?"},
{n:77,type:"mcq",micro:"Titik stasioner majemuk",q:"Sebuah fungsi berpangkat tiga bisa memiliki DUA titik stasioner (satu maksimum lokal dan satu minimum lokal). Cara menemukannya adalah...",options:["Menyetarakan fungsinya dengan nol dan menyelesaikan — hanya ada satu penyelesaian","Menurunkan lagi tanpa menyetarakan dengan nol dan membaca grafik saja","Menyetarakan turunannya dengan nol dan menyelesaikan — bisa ada lebih dari satu penyelesaian"],answer:2,explain:"Menyelesaikan f'(x) = 0 memberi semua titik stasioner; untuk fungsi berpangkat tiga, f'(x) adalah kuadrat yang bisa punya dua akar.",hint:"Persamaan f'(x) = 0 untuk fungsi pangkat tiga berbentuk apa, dan berapa akar yang bisa dimilikinya?"},
{n:78,type:"mcq",micro:"Laju perubahan pada grafik kecepatan-waktu",q:"Pada grafik KECEPATAN-waktu (bukan posisi-waktu), kemiringan grafik mewakili...",options:["Percepatan (laju perubahan kecepatan)","Jarak yang ditempuh","Posisi awal"],answer:0,explain:"Turunan kecepatan terhadap waktu adalah percepatan, jadi kemiringan grafik kecepatan-waktu adalah percepatan. (Luas di bawahnya adalah jarak.)",hint:"Kemiringan grafik selalu 'laju perubahan sumbu tegak terhadap sumbu mendatar' — di sini kecepatan terhadap waktu."},
{n:79,type:"open",micro:"Menghubungkan turunan dan integral secara intuitif",q:"Kecepatan sebuah mobil terhadap waktu digambar sebagai grafik. Jelaskan apa yang diwakili oleh (a) kemiringan grafik itu dan (b) luas di bawah grafik itu.",explain:"Pada grafik kecepatan-waktu: kemiringan = percepatan (turunan), luas di bawah = jarak (integral).",hint:"Kemiringan selalu 'laju perubahan'; luas di bawah kurva selalu 'akumulasi total'.",sample:"(a) Kemiringan grafik kecepatan-waktu menunjukkan seberapa cepat kecepatan berubah — yaitu percepatan (atau perlambatan jika kemiringannya negatif). Ini adalah gagasan turunan. (b) Luas di bawah grafik kecepatan-waktu (antara kurva dan sumbu waktu) menunjukkan total jarak yang ditempuh, karena jarak = kecepatan × waktu, dan luas menjumlahkan potongan-potongan kecil kecepatan × selang waktu. Ini adalah gagasan integral. Turunan dan integral adalah dua operasi yang saling berkebalikan."},
{n:80,type:"mcq",micro:"Kesalahan menganggap turunan = nilai fungsi",q:"Seorang siswa menghitung f'(x) = 2x untuk f(x) = x², lalu menjawab 'kemiringan di x = 5 adalah 25 karena f(5) = 25'. Apa kesalahannya?",options:["Tidak ada kesalahan","Kemiringan di x = 5 adalah f'(5) = 2 × 5 = 10, bukan f(5)","Seharusnya f(5) = 10"],answer:1,explain:"Kemiringan diberikan oleh f'(x), bukan f(x). f'(5) = 2 × 5 = 10 adalah kemiringan; f(5) = 25 hanyalah tinggi kurva di sana.",hint:"Untuk kemiringan, substitusikan ke f'(x) atau ke f(x)?"},
{n:81,type:"open",micro:"Proyek mini",q:"Proyek Mini: Ambil data jarak tempuh terhadap waktu untuk sebuah perjalanan nyata (misalnya jarak yang ditempuh saat berjalan kaki dicatat tiap 30 detik selama beberapa menit). Hitung kecepatan rata-rata seluruh perjalanan, lalu hitung kecepatan rata-rata pada dua selang kecil yang berbeda. Bandingkan ketiga angka itu dan jelaskan mengapa berbeda.",explain:"Membandingkan laju rata-rata pada selang besar dan selang-selang kecil menunjukkan langsung mengapa 'rata-rata' berbeda dari 'apa yang terjadi di setiap momen'.",hint:"Bagi jarak dengan waktu untuk keseluruhan, lalu ulangi untuk dua potongan kecil yang berbeda.",sample:"Contoh data: 0 s → 0 m; 30 s → 40 m; 60 s → 70 m; 90 s → 130 m; 120 s → 150 m. Kecepatan rata-rata seluruh perjalanan = 150 m ÷ 120 s = 1,25 m/s. Selang 60–90 s: (130 − 70) ÷ 30 = 2,0 m/s (bagian cepat). Selang 90–120 s: (150 − 130) ÷ 30 ≈ 0,67 m/s (bagian lambat). Ketiganya berbeda karena kecepatan berubah sepanjang perjalanan: rata-rata keseluruhan menyembunyikan bahwa ada bagian cepat dan bagian lambat, yang terlihat saat kita melihat selang-selang kecil."},
{n:82,type:"mcq",micro:"Kecepatan dari s(t) = t²",q:"Posisi sebuah benda adalah s(t) = t² meter (t dalam detik). Berapa kecepatan sesaatnya pada t = 3 detik?",options:["9 m/detik","3 m/detik","6 m/detik"],answer:2,explain:"v(t) = s'(t) = 2t, jadi v(3) = 2 × 3 = 6 m/detik.",hint:"Turunkan s(t) = t² untuk mendapat v(t), lalu masukkan t = 3."},
{n:83,type:"mcq",micro:"Kecepatan konstan dari s(t) = 5t",q:"Posisi sebuah benda adalah s(t) = 5t + 2. Berapa kecepatannya, dan apakah berubah terhadap waktu?",options:["5 m/detik, tetap sepanjang waktu","5t m/detik, bertambah","2 m/detik, tetap"],answer:0,explain:"v(t) = s'(t) = 5 (turunan 5t adalah 5, turunan konstanta 2 adalah 0). Kecepatannya tetap — gerak lurus beraturan.",hint:"Turunan fungsi linear adalah koefisien di depan t."},
{n:84,type:"open",micro:"Optimasi luas dengan turunan",q:"Kamu punya 20 m pagar untuk membuat kandang persegi panjang. Jika sisinya x dan (10 − x), luasnya A(x) = x(10 − x) = 10x − x². Gunakan turunan untuk mencari nilai x yang memberi luas maksimum, lalu hitung luas maksimum itu.",explain:"Optimasi dengan turunan: susun besaran yang dimaksimalkan sebagai fungsi satu variabel, setarakan turunannya dengan nol, lalu pastikan itu maksimum.",hint:"Turunkan A(x), setarakan dengan nol untuk mencari x, lalu masukkan kembali ke A(x).",sample:"A(x) = 10x − x². Turunan: A'(x) = 10 − 2x. Titik stasioner: 10 − 2x = 0, jadi x = 5. Karena A(x) adalah parabola yang membuka ke bawah (koefisien x² negatif), titik stasioner ini adalah MAKSIMUM. Luas maksimum: A(5) = 10(5) − 5² = 50 − 25 = 25 m². (Sisi-sisinya 5 dan 5 — sebuah persegi.)"},
{n:85,type:"mcq",micro:"Nilai maksimum dari fungsi kuadrat",q:"Fungsi keuntungan sebuah usaha adalah f(x) = −2x² + 40x − 50 (x jumlah barang, dalam ribuan rupiah). f'(x) = −4x + 40. Pada nilai x berapa keuntungan maksimum tercapai?",options:["x = 5","x = 10","x = 40"],answer:1,explain:"Setarakan turunan dengan nol: −4x + 40 = 0, jadi x = 10. Karena koefisien x² negatif, ini titik maksimum.",hint:"Selesaikan −4x + 40 = 0."},
{n:86,type:"mcq",micro:"Nilai keuntungan maksimum",q:"Untuk f(x) = −2x² + 40x − 50 dengan maksimum di x = 10, berapa nilai keuntungan maksimumnya?",options:["350","110","150"],answer:2,explain:"f(10) = −2(100) + 40(10) − 50 = −200 + 400 − 50 = 150 (ribu rupiah).",hint:"Substitusikan x = 10 ke f(x) yang asli."},
{n:87,type:"open",micro:"Kapan benda berhenti sesaat",q:"Sebuah bola dilempar ke atas dengan tinggi h(t) = −5t² + 20t meter. Kecepatannya v(t) = h'(t). Cari v(t), lalu tentukan pada waktu t berapa bola berhenti sesaat (kecepatan nol) — yaitu saat mencapai tinggi maksimum.",explain:"Di titik tertinggi lintasan, bola berhenti sesaat sebelum jatuh kembali — kecepatannya nol, yang berarti turunan tinggi terhadap waktu sama dengan nol.",hint:"Turunkan h(t), setarakan hasilnya dengan nol, dan selesaikan untuk t.",sample:"h(t) = −5t² + 20t. v(t) = h'(t) = −10t + 20. Bola berhenti sesaat saat v(t) = 0: −10t + 20 = 0, jadi t = 2 detik. (Pada saat ini bola berada di puncak lintasannya; tingginya h(2) = −5(4) + 20(2) = −20 + 40 = 20 m.)"},
{n:88,type:"mcq",micro:"Turunan kedua dan bentuk kurva",q:"Untuk f(x) = x², turunan pertamanya f'(x) = 2x dan turunan keduanya f''(x) = 2 (positif). Turunan kedua yang positif menandakan grafik...",options:["Cekung ke atas (berbentuk seperti mangkuk)","Cekung ke bawah","Berupa garis lurus"],answer:0,explain:"Turunan kedua positif berarti kemiringan terus bertambah, sehingga kurva melengkung ke atas seperti mangkuk (cekung ke atas).",hint:"Jika kemiringan (f') terus bertambah seiring x, kurvanya melengkung ke arah mana?"},
{n:89,type:"open",micro:"Menganalisis fungsi secara lengkap",q:"Diberikan f(x) = x² − 10x + 21. Cari f'(x), titik stasionernya, nilai fungsi di titik itu, dan tentukan apakah maksimum atau minimum. Lalu sebutkan pada selang x mana fungsi ini turun dan pada selang mana naik.",explain:"Analisis fungsi lengkap: turunan memberi titik stasioner, arah bukaan (atau tanda turunan di sekitarnya) memberi jenisnya, dan tanda turunan memberi selang naik/turun.",hint:"Selesaikan f'(x) = 0, cek tanda parabola, lalu periksa tanda f'(x) di kiri dan kanan titik stasioner.",sample:"f'(x) = 2x − 10. Titik stasioner: 2x − 10 = 0 → x = 5. Nilai: f(5) = 25 − 50 + 21 = −4, jadi titik stasioner di (5, −4). Karena koefisien x² positif (parabola membuka ke atas), ini MINIMUM. Tanda turunan: untuk x < 5, f'(x) < 0 → fungsi TURUN pada selang x < 5; untuk x > 5, f'(x) > 0 → fungsi NAIK pada selang x > 5."},
{n:90,type:"mcq",micro:"Jarak dari grafik kecepatan-waktu",q:"Sebuah mobil bergerak dengan kecepatan tetap 20 m/detik selama 8 detik. Pada grafik kecepatan-waktu, luas di bawah grafiknya (persegi panjang 20 × 8) adalah 160. Angka 160 mewakili...",options:["Kecepatan akhir mobil","Jarak total yang ditempuh (160 meter)","Percepatan mobil"],answer:1,explain:"Luas di bawah grafik kecepatan-waktu sama dengan jarak: 20 m/detik × 8 detik = 160 meter.",hint:"Luas = tinggi × lebar = kecepatan × waktu = ?"},
{n:91,type:"mcq",micro:"Turunan suku pecahan sederhana",q:"Untuk f(x) = 0,5x², berapa f'(x)?",options:["0,5x","x²","x"],answer:2,explain:"Turunan 0,5x² = 0,5 × (2x) = x.",hint:"Turunkan x² menjadi 2x, lalu kalikan dengan koefisien 0,5."},
{n:92,type:"open",micro:"Membandingkan dua tafsiran laju",q:"Nilai ujian seorang siswa terhadap jumlah jam belajar dimodelkan f(x). Diketahui laju perubahan rata-rata dari x = 0 ke x = 10 jam adalah 6 poin per jam, tetapi f'(10) = 1 poin per jam. Jelaskan apa arti kedua angka ini dan apa yang mereka sarankan tentang belajar tambahan setelah 10 jam.",explain:"Laju rata-rata merangkum seluruh selang; laju sesaat menunjukkan manfaat tambahan tepat pada titik itu — di sini menandakan hasil yang menurun.",hint:"Satu angka tentang keseluruhan 10 jam; satu angka tentang jam ke-11 saja. Mana yang lebih relevan untuk memutuskan belajar lebih lama?",sample:"Laju rata-rata 6 poin/jam berarti selama 10 jam pertama belajar, nilai naik total 60 poin — rata-rata 6 poin untuk tiap jam. f'(10) = 1 poin/jam adalah laju SESAAT pada titik 10 jam: menambah satu jam belajar lagi setelah 10 jam hanya menaikkan nilai sekitar 1 poin. Ini menunjukkan 'hasil yang menurun': jam-jam belajar pertama sangat bermanfaat (curam), tetapi setelah 10 jam manfaat tambahan tiap jam sudah kecil (landai). Belajar lebih dari 10 jam memberi peningkatan yang jauh lebih sedikit per jamnya."},
{n:93,type:"mcq",micro:"Laju perubahan volume",q:"Sebuah balon diisi sehingga volumenya V(t) = 4t² cm³ (t dalam detik). Laju perubahan volume V'(t) = 8t. Pada t = 5 detik, volumenya bertambah dengan laju...",options:["40 cm³ per detik","100 cm³ per detik","20 cm³ per detik"],answer:0,explain:"V'(t) = 8t, jadi V'(5) = 8 × 5 = 40 cm³ per detik.",hint:"Turunkan V(t) = 4t² untuk mendapat V'(t), lalu substitusikan t = 5."},
{n:94,type:"open",micro:"Optimasi biaya",q:"Biaya bahan bakar sebuah truk per perjalanan bergantung pada kecepatan v (km/jam) menurut C(v) = (3600 ÷ v) + v (dalam ribuan rupiah). Turunannya C'(v) = −3600 ÷ v² + 1. Cari kecepatan yang meminimalkan biaya dengan menyetarakan C'(v) dengan nol.",explain:"Optimasi dengan turunan juga berlaku untuk meminimalkan: setarakan turunan dengan nol untuk menemukan titik stasioner yang meminimalkan biaya.",hint:"Selesaikan −3600/v² + 1 = 0 untuk v (ambil nilai positif).",sample:"Setarakan C'(v) = 0: −3600/v² + 1 = 0, jadi 1 = 3600/v², jadi v² = 3600, jadi v = 60 km/jam (mengambil nilai positif karena kecepatan). Pada v = 60, biaya C(60) = 3600/60 + 60 = 60 + 60 = 120 ribu rupiah. Kecepatan 60 km/jam meminimalkan biaya bahan bakar per perjalanan: lebih lambat berarti banyak waktu di jalan (suku 3600/v besar), lebih cepat berarti boros bahan bakar (suku v besar)."},
{n:95,type:"mcq",micro:"Turunan menunjukkan fungsi tak berubah",q:"Suhu suatu ruangan berpendingin dijaga tetap. Jika suhu dimodelkan T(t), maka sepanjang waktu itu T'(t) bernilai...",options:["Selalu berubah-ubah","Nol (suhu tidak berubah, jadi laju perubahannya nol)","Positif besar"],answer:1,explain:"Suhu yang dijaga tetap berarti tidak ada perubahan, sehingga turunannya (laju perubahan) adalah nol sepanjang waktu itu.",hint:"Jika nilai T tidak berubah seiring t, berapa laju perubahannya?"},
{n:96,type:"mcq",micro:"Membaca percepatan dari grafik kecepatan",q:"Sebuah grafik kecepatan-waktu berupa garis lurus dari (0, 0) naik ke (4, 20). Kemiringannya adalah...",options:["20 m/detik","4 m/detik²","5 m/detik² (percepatan konstan)"],answer:2,explain:"Kemiringan = (20 − 0) ÷ (4 − 0) = 5. Pada grafik kecepatan-waktu, kemiringan ini adalah percepatan, yaitu 5 m/detik².",hint:"Kemiringan = perubahan kecepatan ÷ perubahan waktu, dan pada grafik ini kemiringan berarti percepatan."},
{n:97,type:"open",micro:"Menghubungkan tiga fungsi gerak",q:"Sebuah benda memiliki posisi s(t) = t³ − 6t² + 9t. Cari fungsi kecepatan v(t) dan tentukan pada waktu t berapa saja benda itu berhenti sesaat (v = 0).",explain:"Menurunkan fungsi posisi berpangkat tiga memberi fungsi kecepatan berpangkat dua, yang bisa punya dua akar — dua waktu benda berhenti sesaat.",hint:"Turunkan s(t) menjadi v(t), setarakan v(t) dengan nol, lalu selesaikan persamaan kuadratnya.",sample:"v(t) = s'(t). Turunan t³ adalah 3t²; turunan −6t² adalah −12t; turunan 9t adalah 9. Jadi v(t) = 3t² − 12t + 9. Benda berhenti sesaat saat v(t) = 0: 3t² − 12t + 9 = 0. Bagi dengan 3: t² − 4t + 3 = 0. Faktorkan: (t − 1)(t − 3) = 0, jadi t = 1 atau t = 3. Benda berhenti sesaat pada t = 1 detik dan t = 3 detik (di antara kedua waktu itu benda bergerak mundur, karena v(t) negatif)."},
{n:98,type:"mcq",micro:"Turunan dari jumlah beberapa suku",q:"Untuk f(x) = 2x³ − 4x² + 7x − 1, berapa f'(x)?",options:["6x² − 8x + 7","6x³ − 8x² + 7x","2x² − 4x + 7"],answer:0,explain:"Turunkan tiap suku: 2x³ → 6x²; −4x² → −8x; 7x → 7; −1 → 0. Jadi f'(x) = 6x² − 8x + 7.",hint:"Terapkan aturan pangkat pada setiap suku dan hilangkan suku konstanta."},
{n:99,type:"mcq",micro:"Menafsirkan turunan sama dengan nol dalam konteks",q:"Ketinggian air pasang di sebuah pelabuhan dimodelkan h(t). Pada momen ketika h'(t) = 0, air sedang...",options:["Tepat di ketinggian nol","Pada titik pasang tertinggi atau surut terendah (sesaat tidak naik maupun turun)","Naik paling cepat"],answer:1,explain:"h'(t) = 0 berarti ketinggian air sesaat tidak berubah — ini terjadi tepat di puncak pasang atau dasar surut, sebelum arahnya berbalik.",hint:"Kapan ketinggian air 'berhenti' sesaat sebelum berbalik arah?"},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali unit Pengantar Kalkulus ini — dari laju perubahan rata-rata dan kecuraman yang berubah, ke garis singgung dan gagasan limit, hingga aturan pangkat serta memakai turunan untuk mencari titik maksimum dan minimum — kebiasaan apa yang sekarang kamu miliki saat menghadapi soal tentang perubahan, kecepatan, atau nilai optimum?",explain:"Menyebutkan satu kebiasaan baru yang konkret adalah tanda paling jelas bahwa keterampilan ini sudah tertanam.",hint:"Ingat momen dalam unit ini yang mengubah cara kamu menyikapi kata 'laju', 'kecepatan', atau 'nilai terbaik'.",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti membedakan dengan sadar antara 'rata-rata sepanjang selang' dan 'sesaat pada satu momen', mengenali bahwa kemiringan/laju diberikan oleh f'(x) bukan f(x), otomatis menyetarakan turunan dengan nol untuk mencari titik maksimum/minimum, atau menafsirkan tanda turunan (positif = naik, negatif = turun, nol = mendatar) dalam situasi nyata seperti biaya, populasi, atau ketinggian."},
];
